from taf.ul.power_ue.devices import (
    FastMile,
    Samsung,
    HarmonyHonor,
    MediaTek,
    Xiaomi,
    Qualcomm,
    HuaweiAndroid,
)
from taf.ul.power_ue.exception import UeUnsupported


class SupportedPowerUeDevices(object):
    # {ue selector: class}

    _ue_selector_vs_class = {
        "fastmile": FastMile,
        "samsung": Samsung,
        "harmony": HarmonyHonor,
        "mtk": MediaTek,
        "xiaomi": Xiaomi,
        "qualcomm": Qualcomm,
        "huaweiandroid": HuaweiAndroid,
    }

    @classmethod
    def lookup_device(cls, ue_selector=None):
        ue_class = cls._ue_selector_vs_class.get(ue_selector.lower())
        if not ue_class:
            raise UeUnsupported(
                "ue selector '{}' is not in supported list '{}'".format(
                    ue_selector, cls._ue_selector_vs_class
                )
            )

        return ue_class
